#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, M;
    cin >> n >> M;

    vector<long long> dp(n + 1, 0);
    vector<long long> accu(n + 1, 0);

    dp[1] = 1;
    if (n >= 2) {
        dp[2] = 1;
    }
    accu[1] = 1;
    if (n >= 2) {
        accu[2] = 2;
    }
    long long extra = 0; // Not used in the code, but declared for completeness

    for (int i = 3; i <= n; ++i) {
        dp[i] = accu[i - 1];
        int limit = static_cast<int>(sqrt(i));
        for (int j = 1; j <= limit; ++j) {
            if (i % j == 0) {
                dp[i] += dp[j];
                dp[i] %= M;
                if (j > 1 && j * j < i) {
                    dp[i] += dp[i / j];
                    dp[i] %= M;
                }
            }
        }
        accu[i] = (accu[i - 1] + dp[i]) % M;
    }

    cout << accu[n] << "\n";

    return 0;
}
